from __future__ import annotations

from dataclasses import dataclass

import numpy as np


BOHR_TO_ANGSTROM = 0.529177210903


@dataclass(frozen=True)
class GridField:
    values: np.ndarray
    weights: np.ndarray
    length_unit: str


@dataclass(frozen=True)
class PortableGrid:
    density: np.ndarray
    cell_weights: np.ndarray
    length_unit: str


def pack_grid_field(field: GridField) -> PortableGrid:
    volume_factor = BOHR_TO_ANGSTROM**3
    return PortableGrid(
        density=np.asarray(field.values / volume_factor),
        cell_weights=np.asarray(field.weights * volume_factor),
        length_unit="angstrom",
    )


def unpack_grid_field(payload: PortableGrid) -> GridField:
    if payload.length_unit != "angstrom":
        raise ValueError(f"Unsupported portable grid unit: {payload.length_unit}")
    return GridField(
        values=np.asarray(payload.density),
        weights=np.asarray(payload.cell_weights),
        length_unit=payload.length_unit,
    )
