def _integrated_field(field: GridField) -> float:
    value = float(np.dot(field.values, field.weights))
    if value <= 0.0:
        raise ValueError("Cannot evaluate an empty grid field")
    return value


def screening_parameter_from_field(field: GridField) -> float:
    total = _integrated_field(field)
    switch = erf(total * field.values / RHO_IN)
    mask = field.values > EPSILON
    integrand = np.zeros_like(field.values)
    integrand[mask] = (
        (3.0 / (4.0 * np.pi * field.values[mask])) ** (1.0 / 3.0)
        * switch[mask]
    )
    normalization = float(np.dot(switch, field.weights))
    if abs(normalization) < 1e-14:
        raise ZeroDivisionError("screening normalization vanished")
    avg_rs = float(np.dot(integrand, field.weights) / normalization)
    if field.length_unit == "angstrom":
        avg_rs /= BOHR_TO_ANGSTROM
    elif field.length_unit != "bohr":
        raise ValueError(f"Unsupported grid field unit: {field.length_unit}")
    return float(
        OMEGA_EFF_A1 / avg_rs
        + OMEGA_EFF_A2 * avg_rs / (1.0 + OMEGA_EFF_A3 * avg_rs**2)
    )

def _coerce_atom_line(line: str) -> str:
    parts = line.split()
    if len(parts) < 4:
        return line.strip()

    atomic_number_to_symbol = {
        "1": "H",
        "5": "B",
        "6": "C",
        "7": "N",
        "8": "O",
        "9": "F",
        "16": "S",
    }
    if parts[0] in atomic_number_to_symbol:
        parts[0] = atomic_number_to_symbol[parts[0]]
    return " ".join(parts[:4])

