def _coerce_atom_line(line: str) -> str:
    parts = line.split()
    if len(parts) < 4:
        return line.strip()

    # Some bundled geometry files label atoms by nuclear charge instead of by
    # element symbol.  Resolve them through the periodic table shipped with
    # PySCF so that no element list has to be maintained here.
    token = parts[0]
    if token.isdigit():
        parts[0] = ELEMENTS[int(token)]
    return " ".join(parts[:4])


def _electron_count(atom_spec: str, charge: int = 0) -> int:
    """Number of electrons implied by an atom specification."""
    nuclear_charge = sum(
        gto.charge(symbol) for symbol, _coords in gto.mole.format_atom(atom_spec)
    )
    return int(nuclear_charge) - int(charge)


def _default_spin(atom_spec: str, charge: int = 0) -> int:
    """Lowest spin multiplicity compatible with the electron count (2S)."""
    return _electron_count(atom_spec, charge) % 2

