import sys; sys.path.insert(0,'source')
import numpy as np
from pyscf import dft, gto, lib, scf
from pyscf.dft import numint
lib.num_threads(1)
import task002_benchmark as tb
from portable_grid import GridField

def omega(mol, mf, level=1):
    grids = dft.gen_grid.Grids(mol); grids.level=level; grids.build()
    ao = numint.eval_ao(mol, grids.coords)
    dm = np.asarray(mf.make_rdm1())
    if dm.ndim==3: dm = dm[0]+dm[1]
    rho = numint.eval_rho(mol, ao, dm, xctype='LDA')
    return tb.screening_parameter_from_field(GridField(values=rho, weights=grids.weights, length_unit='bohr'))

sysmap = {s.label: s for s in tb.load_validation_study_systems('fragment_epsilon')}
for lab in ("OH", "NCO", "NH2", "CN"):
    mol = tb.build_molecule(sysmap[lab].atom_spec)
    print(f"--- {lab} ---")
    for name in ("plain200", "newton", "newton_from_plain", "levelshift"):
        mf = dft.UKS(mol); mf.xc='PBE'; mf.grids.level=1; mf.conv_tol=1e-9; mf.conv_tol_grad=1e-6; mf.verbose=0
        if name == "plain200":
            mf.max_cycle = 200; mf.kernel()
        elif name == "newton":
            mf = mf.newton(); mf.kernel()
        elif name == "newton_from_plain":
            mf.max_cycle = 50; mf.kernel(); dm = mf.make_rdm1()
            mf = mf.newton(); mf.kernel(dm0=dm)
        else:
            mf.level_shift = 0.3; mf.max_cycle=200; mf.kernel()
            dm = mf.make_rdm1(); mf.level_shift = 0.0; mf.kernel(dm0=dm)
        print(f"  {name:18s} conv={mf.converged!s:5s} E={mf.e_tot:.9f} <S2>={scf.uhf.spin_square(mf)[0]:.4f} omega={omega(mol,mf):.6f}")
